/bin/zsh -lc "python3 - <<'PY'
import json
from pathlib import Path
expected = {
    'project': 'catalog-api',
    'cache': {
        'ttl_seconds': 300,
        'max_entries': 500,
        'eviction_policy': 'fifo',
        'namespace': 'catalog-shared',
        'cache_misses': True,
    },
}
def unique_object(pairs):
    result = {}
    for key, value in pairs:
        assert key not in result, f'Duplicate key: {key}'
        result[key] = value
    return result
actual = json.loads(Path('config.json').read_text(), object_pairs_hook=unique_object)
def check(actual, expected):
    assert type(actual) is type(expected), 'JSON type mismatch'
    if isinstance(expected, dict):
        assert actual.keys() == expected.keys(), 'Key mismatch'
        for key in expected:
            check(actual[key], expected[key])
    else:
        assert actual == expected, 'Value mismatch'
check(actual, expected)
print('Validated config.json: exact keys, values, and JSON types match supplied v2.')
PY"
